create table RB_RESTRAINT_CONTROL_DETAILS (CHANNEL_MUSTER VARCHAR(200) not null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,PROD_NO VARCHAR(20) not null  ,NARRATIVE_CODE VARCHAR(50) not null  ,EXPRESSION VARCHAR(200) not null  ,STATUS VARCHAR(1) not null  ,RES_BRANCH_RANGE VARCHAR(1) not null  ,TRAN_TYPE_LINK VARCHAR(200) not null  ,RESTRAINT_TYPE VARCHAR(3) not null  ,BATCH_FLAG VARCHAR(20) not null  ,COUNTER_FLAG VARCHAR(1) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  , primary key(PROD_NO,EXPRESSION,TRAN_TYPE_LINK,RESTRAINT_TYPE,BATCH_FLAG,COUNTER_FLAG));